@app.post("/test")
def test_endpoint(foo: ArbitraryType = Body()):
    return {"foo": str(foo)}

client = TestClient(app)

def test_arbitrary_type_body():
    # This should fail if arbitrary_types_allowed=False
    # But since we are passing it as a Body parameter, FastAPI creates a BodyModel.
    # If BodyModel doesn't have arbitrary_types_allowed=True, Pydantic will raise an error.
    try:
        response = client.post("/test", json={"foo": "some value"})
        print(f"Response: {response.status_code}, {response.json()}")
        assert response.status_code == 200
    except Exception as e:
        print(f"Caught exception: {e}")
        raise e

if __name__ == "__main__":
    test_arbitrary_type_body()

